#!/bin/bash
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-25
# Scale-up synthetic runs (Fatih 2026-10-25 20:10: "after task 4, if I have not written"): after the family loop is done,
# run the 50 / 100 / 200 / 500-callback descriptors one after another (structural runs). Log: $LD/synth_scale.log
set -u; cd "$(dirname "$0")/.."
LD=$HOME/fish_traces/night_20261025_final; mkdir -p "$LD"
log() { echo "[$(date +%T)] $*" | tee -a "$LD/synth_scale.log"; }
while ! grep -q "SYNTH LOOP DONE" "$LD/synth_loop.log" 2>/dev/null; do sleep 120; done
[ -f "$LD/STOP" ] && { log "STOP file present; not starting"; exit 0; }
log "family loop done; scale runs start"
for D in tests/synth/generated/{er50,layered100,er200,ba500}_s1.json; do
  [ -f "$D" ] || continue; [ -f "$LD/STOP" ] && { log "STOP"; break; }
  N=$(basename "$D" .json); T0=$SECONDS
  log "scale cycle $N"; bash tests/synth/run_synth.sh "$D" > "$LD/synth_$N.log" 2>&1
  NAME=$(python3 -c "import json,sys; print(json.load(open(sys.argv[1]))['name'])" "$D")
  V=$(grep -h "VERDICT" "$HOME"/fish_traces/synth_runs/verify_${NAME}.txt 2>/dev/null | tail -1)
  log "  $N: ${V:-no verdict} $(grep -h 'false positives' "$HOME"/fish_traces/synth_runs/verify_${NAME}.txt 2>/dev/null | tail -1 | cut -c1-100) ($((SECONDS - T0)) s)"
done
log "SCALE RUNS DONE"
